import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/var/spool/reports'
ALLOWED_EXTENSIONS = {'.csv', '.txt', '.log'}

def sanitize_filename(name):
    """Remove directory traversal but preserve the filename."""
    # Strip path separators to prevent directory traversal
    cleaned = name.replace('/', '').replace('\\', '')
    # Remove null bytes
    cleaned = cleaned.replace('\x00', '')
    return cleaned

def validate_extension(filename):
    """Check file extension is allowed."""
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report by processing uploaded data with system tools."""
    report_type = request.form.get('type', 'summary')
    date_range = request.form.get('date_range', 'last_7d')
    output_format = request.form.get('format', 'csv')

    if report_type not in ('summary', 'detailed', 'audit'):
        return jsonify({'error': 'Invalid report type'}), 400

    # Build the report generation command
    # Uses awk to process intermediate data files
    data_path = os.path.join(UPLOAD_DIR, f'{report_type}_data.csv')

    if not os.path.exists(data_path):
        return jsonify({'error': 'No data available for this report type'}), 404

    # The date_range parameter is passed to awk for filtering
    # awk script filters records matching the date range pattern
    awk_script = f"BEGIN {{OFS=\",\"}} /{date_range}/ {{print $1,$2,$3,$4}}"

    try:
        result = subprocess.run(
            ['awk', awk_script, data_path],
            capture_output=True,
            text=True,
            timeout=30
        )

        if result.returncode != 0:
            return jsonify({'error': 'Report generation failed', 'detail': result.stderr}), 500

        # Post-process: apply output format
        lines = result.stdout.strip().split('\n')

        if output_format == 'json':
            records = []
            for line in lines:
                if line:
                    parts = line.split(',')
                    records.append({
                        'date': parts[0] if len(parts) > 0 else '',
                        'category': parts[1] if len(parts) > 1 else '',
                        'amount': parts[2] if len(parts) > 2 else '',
                        'status': parts[3] if len(parts) > 3 else ''
                    })
            return jsonify({'report': records, 'count': len(records)})
        else:
            return app.response_class(
                response=result.stdout,
                mimetype='text/csv',
                headers={'Content-Disposition': f'attachment; filename={report_type}_report.csv'}
            )
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/reports/upload', methods=['POST'])
def upload_data():
    """Upload data file for report processing."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    f = request.files['file']
    filename = sanitize_filename(f.filename)

    if not validate_extension(filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filepath = os.path.join(UPLOAD_DIR, filename)
    f.save(filepath)

    return jsonify({'status': 'uploaded', 'filename': filename}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
